(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lv"] = {"ui":{"skip":"Pāriet uz saturu","back":"← Atpakaļ uz AI-gile","lang.button":"Valoda: {name}","lang.dialog":"Izvēlies valodu","lang.search":"Meklēt valodas","lang.none":"Neviena valoda neatbilst","lang.notYet":"{name} vēl nav iztulkota","theme.aria":"Pārslēgt gaišo un tumšo tēmu","theme.toLight":"Pārslēgt uz gaišo tēmu","theme.toDark":"Pārslēgt uz tumšo tēmu","index.title":"AI-gile: tava MI izstrādes komanda vienā tāfelē","index.description":"AI-gile ir kanban tāfele MI programmēšanas komandām. Tās strādā, kamēr tu guli; tev paliek viena īsa kaudzīte: ko izlemt, ko pārbaudīt un ko pieņemt.","hero.logoAlt":"AI-gile tāfeles ikona","hero.h1.html":"Tava MI izstrādes komanda vienā&nbsp;tāfelē.","hero.alpha":"🐣 Slēgta pirmsalfa","hero.alphaTitle":"Agrīna un nepabeigta: paldies, ka izmēģini!","hero.lede":"Viņi būvē, kamēr tu guli. Pamodies tu atrodi vienu īsu kaudzīti: pāris jautājumu, pāris lietu, ko pārbaudīt, un viens otrs violets dimants. Uzklikšķini, pieņem un atpakaļ pie kafijas.","dl.windows":"Windows lietotne","dl.browser":"Palaid pārlūkā","dl.soon":"Drīzumā","dl.notify":"🔔 Pastāsti, kad atvērsies","dl.notifySmall":"Alfa vai beta","hero.secondary":"Agile, bet komandai nekad nevajag stāvošo rīta kafiju. (Stand-up viņi tāpat rīko.)","pitch.h2":"AI-gile tik vārdos, cik vēlies","pitch.lede":"Izvēlies garumu, no viena vārda līdz 144. Katrs garums ir savs apraksts, uzrakstīts tieši tam. Velc slīdni vai lieto bulttaustiņus.","pitch.rangeLabel":"Garums vārdos","pitch.dice":"🎲 cita versija","pitch.words.zero":"{n} vārdu","pitch.words.one":"{n} vārds","pitch.words.other":"{n} vārdi","pitch.letters.zero":"{n} burtu","pitch.letters.one":"{n} burts","pitch.letters.other":"{n} burti","pitch.chars.zero":"{n} rakstzīmju","pitch.chars.one":"{n} rakstzīme","pitch.chars.other":"{n} rakstzīmes","count.line.html.zero":"Tāfelē šobrīd ir {n} kartīšu","count.line.html.one":"Tāfelē šobrīd ir {n} kartīte","count.line.html.other":"Tāfelē šobrīd ir {n} kartītes","features.aria":"Ko tā dara","f.pile.h":"Viena kaudzīte tev","f.pile.html":"<b>Tev</b> satur visu, kas gaida tevi, no visiem projektiem: jautājumus, lietas, ko pārbaudīt, un uzdevumus, ko var izdarīt tikai cilvēks. Tava rinda parāda, kas ir nākamais un cik tas aizņems.","f.sleep.h":"Komandas, kas strādā, kamēr tu guli","f.sleep.p":"Katram projektam ir līderis un MI aģentu komanda. Komentē kartīti, un komanda pamostas, paveic darbu un atdod to atpakaļ ar soļiem, kurus var izpildīt arī nogurusi cilvēks.","f.tester.h":"Vispirms pārbauda MI testētājs","f.tester.p":"Pirms kaut kas nonāk pie tevis, testētājs izpilda soļus lietotnes kopijā un parāda redzēto ar ekrānuzņēmumu. Pārlapo izturējušos un pieņem ar vienu klikšķi.","f.proof.h":"Pierādījumi, nevis solījumi","f.proof.p":"Katra nodošana parāda, kas mainījies: failus, atšķirības, ekrānuzņēmumus. Nav jāatver katra lietotne, lai redzētu, vai viss gatavs.","f.chat.h":"Tērzē ar saviem līderiem","f.chat.p":"Discord stila josla: viena ikona katram projektam, violeti dimanti tam, kam vajag tevi. Uzraksti līderim ideju; viņš to pārvērš kartītēs un plānā ar pogu ✅ Aiziet.","f.tidy.h":"Pati uztur kārtību","f.tidy.p":"Saistītās kartītes saplūst vienā, juceklīgi nosaukumi tiek sakārtoti, un tokenu pārbaude uztur kodu kompaktu. Mazāk, starp ko pārslēgties, mazāk, par ko domāt.","f.private.h":"Tava, tavā datorā","f.private.li1":"Tāfele darbojas tavā paša datorā un atbild tikai tev.","f.private.li2":"Privātās ziņas starp cilvēkiem ir šifrētas no gala līdz galam.","f.private.li3":"Nekādu kontu, izsekotāju un sīkdatņu.","f.lang.h":"Tavā valodā","f.lang.p":"Vairāk nekā 120 valodu, no holandiešu, velsiešu un japāņu līdz pirātu, Jodas un klingonu valodai, ar ātru pārslēgšanos atpakaļ uz angļu valodu izstrādātāju vārdiem.","tl.aria":"Laika līnija no pirmās sarunas līdz ceļvedim","tl.h2":"No pirmās sarunas līdz tam, kas sekos","tl.lede":"Īsti datumi un laiki tavā laika joslā. Pēc šodienas tas ir plāns, bez solītiem datumiem.","tl.today":"Šodien","tl.planned":"plānots","tl.cards.zero":"{n} kartīšu","tl.cards.one":"{n} kartīte","tl.cards.other":"{n} kartītes","join.h2":"Pievienojies","join.lede":"AI-gile veido viens mazs cilvēks un liels pulks pacietīgu aģentu. Pagaidām tā ir privāta, slēgtā alfā kopā ar draugiem. Vai gribi izmēģināt, kad tā atvērsies?","join.btn":"Pieteikt interesi","join.small":"Mēs uzrakstīsim e-pastu un neko citu","footer.tag":"AI-gile. Nekādu izsekotāju, nekādu sīkdatņu, nekādas stāvošās rīta kafijas.","footer.licence":"Biznesa licence","footer.status":"Statuss","form.sending":"Sūta…","form.failed":"Neizdevās: mēģini vēlāk vēlreiz.","form.offline":"Neizdevās sazināties ar AI-gile: mēģini vēlāk vēlreiz.","interest.title":"AI-gile: pastāsti, kad atvērsies alfa","interest.description":"Atstāj savu e-pastu, lai uzzinātu, kad atvērsies AI-gile slēgtā alfa vai beta.","interest.h1":"🔔 Pastāsti, kad atvērsies","interest.lede":"AI-gile ir slēgtā pirmsalfā. Atstāj e-pastu, un mēs uzrakstīsim vienreiz, kad tev būs vieta.","interest.email":"Tavs e-pasts","interest.which":"Kuru testu?","interest.alpha":"Slēgtā alfa: agrīna, raupja, daudz izmaiņu","interest.beta":"Beta: stabilāka, vēlāk","interest.both":"Jebkuru, kas būs pirmā","interest.submit":"Pieraksti mani sarakstā","interest.thanks":"Paldies! Tu esi sarakstā.","interest.kept":"Tiek glabāts tikai tavs e-pasts un izvēlētais tests, tikai šim sarakstam. Nekādu jaunumu vēstuļu, nekādu izsekotāju.","licence.title":"AI-gile: biznesa licence","licence.description":"Lieto AI-gile savā uzņēmumā? Pieprasi bezmaksas biznesa licenci.","licence.h1":"📜 Biznesa licence","licence.lede":"Lieto AI-gile darbā? Pastāsti, kas tu esi un ar ko nodarbojies. Ja tas nes kādu labumu, licence ir bez maksas.","licence.company":"Uzņēmums","licence.website":"Tīmekļa vietne","licence.what":"Ar ko nodarbojies","licence.how":"Kā tas palīdz pasaulei","licence.email":"E-pasts","licence.submit":"Pieteikties","licence.thanks":"Paldies! Atbildēsim pa e-pastu.","status.title":"AI-gile statuss","status.h1":"AI-gile statuss","status.quiet":"Viss mierīgi","status.checking":"Pārbauda…","status.offline":"Šobrīd nevar sazināties ar statusa pakalpojumu (mēģina vēlreiz)","status.updated":"atjaunināts {ago}","status.justNow":"tikko","status.min":"pirms {n} min","status.hours":"pirms {n} h","status.days":"pirms {n} d","live.h2":"Skaties, kā tas top, tiešraidē","live.caption":"Katra kartīte ir paslēpta: tu redzi darba formu, nevis vārdus.","live.watching.one":"tiešraidē: {n} skatās","live.watching.other":"tiešraidē: {n} skatās","live.offline":"Tiešraides tāfele mazliet atpūšas. Ieskaties drīz vēlreiz.","live.cols":"Backlogs|Darāmais|Procesā|Komanda pārbauda|Gaida tavu testu|Komandai|Izdarīts","live.last.now":"Pēdējā kartīte pārvietota tikko","live.last.min.one":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.min.other":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.hour.one":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.hour.other":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.day.one":"Pēdējā kartīte pārvietota pirms {n} d.","live.last.day.other":"Pēdējā kartīte pārvietota pirms {n} d."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Deleģēts."]},{"n":2,"texts":["Robotu kanban.","Aģenti, sakārtoti.","Idejas, uzbūvētas."]},{"n":3,"texts":["Kanban robotiem.","Idejas kļūst funkcijās.","Bezmaksas aģentu kanban."]},{"n":5,"texts":["Kanban tāfele, ko vada aģenti.","Tu raksti kartītes. Aģenti būvē.","Bezmaksas, vietēja, pārbaudīta, mazliet jocīga."]},{"n":8,"texts":["Bezmaksas kanban tāfele, kur strādā MI aģenti.","Uzraksti ideju. Aģenti to uzbūvē. Tu to pieņem.","Agile vienam cilvēkam un daudziem pacietīgiem robotiem."]},{"n":13,"texts":["Kanban tāfele tavā datorā, kurā kartītes pa vienai paņem MI aģenti, kamēr tu atpūties.","Uzraksti ideju. To uzbūvē aģentu komanda. Pēc tam testētājs to rūpīgi pārbauda un parāda.","Bez kontiem, bez izsekotājiem: tāfele, daži roboti un tu, kas visu izlemj."]},{"n":21,"texts":["AI-gile ir kanban tāfele darbam ar MI programmēšanas aģentiem. Viņi paņem kartītes, bet tu tās pārbaudi un pieņem.","Katram projektam ir savs līderis un MI aģentu komanda. Komentē jebkuru kartīti, un komanda uzreiz ķeras pie darba.","Bezmaksas personīga darāmo lietu tāfele, kas darbojas tavā datorā. Darbinieki ir roboti. Tas, kurš saka jā, esi tu."]},{"n":34,"texts":["Tu liec idejas uz tāfeles. MI aģentu komanda pārvērš tās strādājošās funkcijās, pārbauda un atdod atpakaļ ar soļiem, kā izmēģināt. Nekas nav gatavs, kamēr tu to neesi pateicis.","AI-gile ir mājās darināta kanban tāfele, ko uzbūvēja Rich, lielā mērā ar to aģentu palīdzību, kurus tā tagad vada. Tā ir bezmaksas, darbojas tavā datorā un tiek dalīta ar draugiem, nevis pārdota.","Iedomājies parastu kanban tāfeli ar kolonnām no Backloga līdz Izdarītam, tikai kartītes paņem MI aģenti. Viņi ziņo par progresu, jautā, kad iestrēguši, un vienmēr gaida tavu īkšķi uz augšu."]},{"n":55,"texts":["AI-gile ir kanban tāfele, kurā komanda sastāv no MI aģentiem. Katram projektam ir līderis, kas plāno darbu, un palīgi, kas to būvē. Kad funkcija ir gatava, MI testētājs to izmēģina un uzņem ekrānuzņēmumu, tad tā nonāk tavā kaudzītē. Pieņem to vai komentē, un viņi darbu pārstrādā.","Tas sākās kā viena cilvēka veids, kā sekot daudzām MI programmēšanas sesijām vienlaikus, un izauga par īstu tāfeli. Tā darbojas tavā datorā, nevajag konta un nav izsekotāju. Tā ir bezmaksas draugiem un ikvienam ziņkārīgajam. Tā ir arī nepabeigta, tāpēc gaidi raupjas malas un reizēm kādu pārsteigumu.","Lūk, godīgā versija. Idejas tev joprojām jāizdomā, un rezultāti tev joprojām jāpārbauda. AI-gile dara visu pa vidu: tur kārtībā kartītes, pamodina īsto aģentu, kad tu komentē, parāda, kas tieši mainījies, un visu savāc vienā īsā kaudzītē, lai tev nav jāmeklē pa visiem projektiem un jāpārslēdzas starp lietotnēm."]},{"n":89,"texts":["AI-gile ir bezmaksas kanban tāfele, ko tu palaid savā datorā. Cilvēku vietā katram projektam ir sava MI aģentu komanda: līderis, kas tavas idejas pārvērš kartītēs un plānā, un palīgi, kas kartītes ķer pēc prioritātes. Kad kaut kas uzbūvēts, MI testētājs izpilda testa soļus un parāda, ko redzēja. Tad tas gaida vienā kaudzītē ar nosaukumu Tev. Tu to pieņem vai komentē, un komanda mēģina vēlreiz, ja vajag. Līdz Izdarīts nekas nenonāk bez tevis.","Dažas lietas, ko varbūt negaidi. Nakts sardze, kamēr tu guli, papildina kolonnu Darāmais ar kartītēm, kurām nevajag tavu atbildi. Tokenu skaitītājs rāda, cik aģenti šodien un šonedēļ iztērējuši, un režīms Bez tokeniem liek viņiem pārstāt tērēt. Tu vari rakstīt draugiem, un privātās ziņas ir šifrētas no gala līdz galam. Tāfele runā aptuveni 120 valodās, tostarp holandiešu, flāmu, pirātu un klingonu. Nekas no tā nemaksā ne santīma, un neviens arī necenšas tev to pārdot.","AI-gile ir neliels personīgs projekts, nevis uzņēmums. Rich gribēja pieskatīt vairākus MI programmēšanas projektus, neatverot katru lietotni, tāpēc viņš un aģenti uzbūvēja tāfeli, un tad ar to uzbūvēja pārējo pašu. Tā ir slēgtā pirmsalfā, kas nozīmē, ka lielākoties tā darbojas, bet to izmēģina tikai daži draugi. Neviens neko nepārdod, neviens nevāc tavus datus. Nav cenu lapas, nav jaunumu vēstuļu un nav izaugsmes plāna. Ja šķiet noderīgi, vari pieteikties izmēģināt, kad tā atvērsies nedaudz plašāk."]},{"n":144,"texts":["AI-gile ir kanban tāfele vienam cilvēkam un daudziem MI aģentiem. Tā darbojas tavā paša datorā un ir pilnīgi bezmaksas. Tu pievieno projektus, un katram projektam ir līderis un neliela komanda. Tu tērzē ar līderi, mazliet kā Discord, un apraksti ideju; līderis to pārvērš kartītēs un plānā, un tad gaida, kad nospiedīsi Aiziet. Komanda kartītes izstrādā pēc prioritātes, izmantojot vienkāršu komandrindu, kas radīta valodas modeļiem. Pirms kaut kas atgriežas pie tevis, MI testētājs izpilda soļus lietotnes kopijā un pievieno ekrānuzņēmumu. Pabeigtais darbs nonāk tavā kaudzītē kopā ar mainītajiem failiem un atšķirībām. Tu to pieņem vai atstāj komentāru, un komanda pamostas un mēģina vēlreiz. Tāfele sevi arī uzkopj: saistītās kartītes tiek apvienotas, un juceklīgi nosaukumi sakārtoti. Kartīti uz Izdarīts var pārvietot tikai tu. Neviens cits to nevar, pat visizcilākais aģents ne.","Aptuveni tāda ir diena ar AI-gile. Vakarā tu atstāj dažus komentārus: šī poga ir nepareizā vietā, šis saraksts jākārto, vai varētu būt tumšais režīms. Tu ej gulēt. Aģenti izlasa komentārus, veic izmaiņas, pārbauda tās un atdod tev atpakaļ. Ja Darāmais izsīkst, nakts sardze to papildina no backloga ar kartītēm, kurām nevajag tavu atbildi. Rītā ir viena īsa kaudzīte: pāris jautājumu un dažas lietas, ko izmēģināt, katrai ar soļiem, ko var izpildīt miegains cilvēks, un ekrānuzņēmumu, kā tas strādā. Tu pārklikšķini, pieņem labās un atsūti atpakaļ pārējās. Ja kaut kas nav skaidrs, tu vienkārši komentē, un tas atkal nonāk pie komandas. Tokenu skaitītājs rāda, cik tas viss patērēja, un režīms Bez tokeniem ir tievām nedēļām. Tad tu brokasto, kam aģenti vēl nevar palīdzēt.","Vispirms, kas AI-gile nav. Tas nav jaunuzņēmums, tas netiek pārdots, un neviens nevāc tavus datus. Tā ir bezmaksas tāfele, kas darbojas tavā datorā, bez kontiem, bez izsekotājiem un bez sīkdatnēm. Kas tā ir: viena kārtīga vieta, kur uzreiz redzēt visus MI programmēšanas projektus, kur kartītes dara aģentu komanda, bet lēmumus pieņem tu. Tajā ir arī nakts sardze, kas kartītes sagatavo, kamēr tu guli. Tā apvieno saistītās kartītes, sakārto juceklīgus nosaukumus un pieskata, cik kompakts paliek kods. Tā runā aptuveni 120 valodās, no holandiešu un flāmu līdz pirātu un klingonu. Draugi var sūtīt viens otram ziņas, privāti un šifrēti. To uzbūvēja Rich un liels pulks pacietīgu aģentu, galvenokārt izmantojot pašu tāfeli. Tā ir slēgtā pirmsalfā, tāpēc dažviet vēl ir raupja. Ja šķiet jautri, pieklājīgi pajautā, un varbūt tiksi iekšā agrāk."]}],"quips":{"1":"Viens vārds. Drosmīgi. Varbūt pat pārāk drosmīgi.","3":"Trīs vārdi. Jau godīgāk nekā vairums produktu lapu.","8":"Astoņi vārdi. Joprojām īsāk par stand-up.","21":"Garumi, starp citu, ir stāstu punkti. Protams, ka ir.","55":"Piecdesmit pieci vārdi. Kamēr tu to lasīji, divas kartītes tika pabeigtas.","144":"Tas ir garais. 233 nav. Aģenti ir aizgājuši gulēt."}},"timeline":{"first-idea.name":"Pirmā ideja","first-idea.line":"Pati pirmā saruna, pirms vēl bija kāds kods.","first-board.name":"Pirmā tāfele","first-board.line":"Tāfele, kas seko savai būvei: kartītes, kolonnas, vilkšana, projekti.","team-roles.name":"Komanda un lomas","team-roles.line":"Aģentu profili, komandu veidnes, telpas un kurš ko dara.","install.name":"Uzstādīšana un laidieni","install.line":"Zip, ko draugs var uzstādīt, pašatjaunināšanās, kanāli un atgriešanās.","usage-saver.name":"Patēriņa taupītājs","usage-saver.line":"Mēra, cik izmaksā darbs, uztur kodu kompaktu, taupa tavu limitu.","friends.name":"Draugi un kopīgošana","friends.line":"Privātas ziņas, sajaukts releja kanāls, ielūgumi, lomas un kopīgi projekti.","languages.name":"Valodas","languages.line":"Katrs ekrāna teksts valodas failā, vispirms holandiešu un flāmu valoda.","ai-tester.name":"MI testētājs","ai-tester.line":"Testētājs vispirms pārbauda katru nodošanu un parāda redzēto.","website.name":"Mājaslapa","website.line":"aigile.lol, ievada lapa un šī laika līnija.","streaming.name":"Tērzēšana un straumēšana","streaming.line":"Discord, Twitch, OBS, straumētāja režīms, GIF un emocijzīmes.","no-ai.name":"Izdevums bez MI","no-ai.line":"Tāfele cilvēkiem, kas programmē bez MI, un publiskas tāfeles.","night-watch.name":"Nakts sardze","night-watch.line":"Sargs un Scrum Master notur komandas pie darba, kamēr tu guli.","p-more.name":"Viss pārējais","p-more.line":"Mazākas idejas, kas vēl gaida savu kārtu.","p-android.name":"Telefons un Android","p-android.line":"Piekļuve tāfelei no telefona, pēc tam dabiska Android lietotne.","p-release.name":"Alfa un tālāk","p-release.line":"Slēgtā alfa, dzīvā vietne, tad beta.","p-languages.name":"Vairāk valodu","p-languages.line":"Vairāk nekā simts valodu un iegremdēšanās režīms apguvējiem.","p-engines.name":"Vairāk MI dzinēju","p-engines.line":"Izvēlies Claude, Codex vai Gemini katram aģentam.","p-pro.name":"Profesionāla prakse","p-pro.line":"Riska atzīmes, sapludināšanas vārti, incidentu kartītes un aizsargbarjeras.","p-self.name":"Rūpes par tevi","p-self.line":"Noguruma režīms, atgādinājumi par sevis kopšanu un 4:20.","p-servers.name":"Serveri un mērogs","p-servers.line":"Globāli servera iestatījumi, lomas un plānošana izaugsmei.","p-livestream.name":"Straumēšanas papildinājumi","p-livestream.line":"Twitch tērzētava, pašu emocijzīmes un publisks tiešraides skats."}};
